["from jsonschema import validate

jsonschema = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"},
        "address": {
            "type": "object",
            "properties": {
                "city": {"type": "string", "title": "City"},
                "postcode": {"type": "string", "title": "Postcode"},
                "street": {"type": "string", "title": "Street"}
            },
            "required": ["city", "postcode", "street"],
            "title": "Address"
        },
        "contacts": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "email": {"type": "string", "title": "Email"},
                    "phone": {"type": "string", "title": "Phone"}
                },
                "required": ["email", "phone"],
                "title": "Contact"
            }
        },
        "employment": {
            "type": "object",
            "properties": {
                "company": {"type": "string", "title": "Company"},
                "role": {"type": "string", "title": "Role"},
                "years": {"type": "integer", "maximum": 50, "minimum": 0, "title": "Years"}
            },
            "required": ["company", "role", "years"],
            "title": "Employment"
        },
        "description": {
            "type": "string",
            "title": "Description"
        },
        "tags": {
            "type": "array",
            "items": {"type": "string"}
        }
    },
    "required": ["name", "age", "address", "contacts", "employment", "description", "tags"]
}

def validate_schema(text):
    try:
        validate(instance={"name": "Edsger Dijkstra", "age": 57, "address": {"city": "Cupertino", "postcode": "40212", "street": "88 Königsallee"}, "contacts": [{"email": "edsger.dijkstra@mail.test", "phone": "+13 733 5104"}], "employment": {"company": "Corp", "role": "Distributed-systems", "years": 50}, "description": "Distributed-systems, cryptography", "tags": ["distributed-systems", "cryptography"]}, jsonschema)
        return True
    except Exception as e:
        print(f"Validation error: {e}")
        return False

text = """
Edsger Dijkstra, aged 57, lives at 88 Königsallee in Cupertino. Interests: distributed-systems, cryptography. Contact: edsger.dijkstra@mail.test. Contact: edsger.dijkstra1@corp.example, phone +13 733 5104. The postcode is 40212.
"""

