["from jsonschema import validate

jsonschema = {
    "type": "object",
    "$defs": {
        "Address": {
            "type": "object",
            "description": "A postal address; ``postcode`` is genuinely optional in the rendered prose.",
            "properties": {
                "city": {"type": "string", "title": "City"},
                "postcode": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Postcode"},
                "street": {"type": "string", "title": "Street"}
            },
            "required": ["street", "city"],
            "title": "Address"
        },
        "Contact": {
            "type": "object",
            "description": "One contact method; ``phone`` is often absent.",
            "properties": {
                "email": {"type": "string", "title": "Email"},
                "phone": {"anyOf": [{"type": "string"}, {"type": "null"}], "default": null, "title": "Phone"}
            },
            "required": ["email"],
            "title": "Contact"
        },
        "Employment": {
            "type": "object",
            "description": "Current employment. The whole object is omitted for unemployed records.",
            "properties": {
                "company": {"type": "string", "title": "Company"},
                "role": {"type": "string", "title": "Role"},
                "years": {"type": "integer", "maximum": 50, "minimum": 0, "title": "Years"}
            },
            "required": ["company", "role", "years"],
            "title": "Employment"
        },
        "description": {
            "type": "string",
            "title": "Description"
        },
        "tags": {
            "type": "array",
            "items": {"type": "string"},
            "title": "Tags"
        }
    },
    "required": ["Address", "Contact", "Employment", "description", "tags"]
}

def validate_schema(text):
    try:
        validate(instance={"Address": {"city": "London", "postcode": "95014", "street": "12 Baker St", "company": "Sun Micro", "role": "compiler architect", "years": 26}, "Contact": {"email": "katherine.torvalds@example.com", "phone": "+69 468 5533"}, "Employment": {"company": "Sun Micro", "role": "compiler architect", "years": 26}}, jsonschema)
        return True
    except Exception as e:
        print(f"Validation error: {e}")
        return False

text = """
Katherine Torvalds, aged 40, lives at 12 Baker St in London. Contact: katherine.torvalds@example.com, phone +69 468 5533. The postcode is 95014. They work at Sun Micro as a compiler architect, 26 years so far.
"""

