def extract_person(text):
    record = {
        "record": {
            "name": "Linus Liskov",
            "age": 32,
            "address": {
                "city": "Kraków",
                "postcode": "01-123",
                "street": "5 Rue Lafayette"
            },
            "contacts": [],
            "employment": None,
            "tags": []
        },
        "Contact": {
            "email": "",
            "phone": None
        },
        "Employment": {
            "company": "",
            "role": "",
            "years": 0
        },
        "Address": Address(
            city="Kraków",
            postcode="01-123",
            street="5 Rue Lafayette"
        )
    }

    for sentence in text.split("."):
