    try:
        validate(instance=record, schema=jsonschema)
    except Exception as e:
        print(f"Validation error: {e}")

def extract_person(text):
    record = {
        "name": "",
        "age": 0,
        "address": {
            "street": "",
            "city": "",
            "postcode": "",
            "contact": {
                "email": "",
                "phone": ""
            }
        },
        "employment": {
            "company": "",
            "role": "",
            "years": 0
        },
        "description": "",
        "tags": []
    }
    for line in text.splitlines():
        if line.startswith("Radia Torvalds,"):
            name = line.split(",")[1].strip()
            record["name"] = name
        elif line.startswith("Aged "):
            age = int(line.split(" ")[1])
            record["age"] = age
        elif line.startswith("Lives at "):
            address = line.split(" ")[1].strip()
            record["address"]["street"] = address
            record["address"]["city"] = ""
            record["address"]["postcode"] = ""
            record["address"]["contact"]["email"] = ""
            record["address"]["contact"]["phone"] = ""
        elif line.startswith("Contact: "):
            contact = line.split(" ")[1].strip()
            record["address"]["contact"]["email"] = contact
            record["address"]["contact"]["phone"] = ""
        elif line.startswith("Works at "):
            company = line.split(" ")[1].strip()
            role = line.split(" ")[1].strip()
            years = int(line.split(" ")[1])
            record["employment"]["company"] = company
            record["employment"]["role"] = role
            record["employment"]["years"] = years
        elif line.startswith("Interests: "):
            interests = line.split(" ")[1].strip()
            record["description"] = interests
        elif line.startswith("Distributed-systems: "):
            interests = line.split(" ")[1].strip()
            record["description"] = interests
        elif line.startswith("Cryptography: "):
            interests = line.split(" ")[1].strip()
            record["description"] = interests
        elif line.startswith("21 years so far: "):
            years = int(line.split(" ")[1])
            record["employment"]["years"] = years
        elif line.startswith("In Düsseldorf: "):
            city = line.split(" ")[1].strip()
            record["address"]["city"] = city
"]

